CREATE TABLE ETL_PROCESS.T_LEGACY_CUSTOMER_RETURN_LINE_1 (

	WSHOP_CD VARCHAR(5) COMMENT 'The unique code for the Lidl webshop',
	CUST_ORDER_RETURN_NR VARCHAR(20) NOT NULL COMMENT 'An original return order number',
	CUST_ORDER_RETURN_POS_NR NUMBER(38,0) NOT NULL COMMENT 'A number of an particular position ( product ) in an return order',
	CUST_ORDER_NR VARCHAR(20) COMMENT 'The original order number of the source system',
	CUST_ORDER_POS_NR NUMBER(38,0) COMMENT 'A number of an particular position ( product ) in an order',
	CUST_ORDER_RETURN_CREATE_TMSP TIMESTAMP_TZ(9) COMMENT 'Creation timestamp of the return. ',
	CUST_ORDER_CREATE_TMSP TIMESTAMP_TZ(9) COMMENT 'The date when order was created in source system ( is used in reporting)',
	CUST_ORDER_DT DATE COMMENT 'The date when order was made',
	CUST_ORDER_RETURN_DT DATE COMMENT 'The date when return was made',
	CUST_NR VARCHAR(20) COMMENT 'The customer number from original system',
	PROD_NR VARCHAR(20) COMMENT 'The number for internal onlineshop product, which is country_1 independent',
	PROD_VARIANT_NR VARCHAR(20) COMMENT 'The product variant number',
	PROD_QTY NUMBER(38,5) COMMENT 'Quantity of a particular product returned',
	CURR_CD VARCHAR(5) COMMENT 'Currency code',
	PROD_PRICE_NET_LOCAL_VAL NUMBER(38,5) COMMENT 'Original ( listed ) price of a returned product netto in local currency',
	PROD_PRICE_GROSS_LOCAL_VAL NUMBER(38,5) COMMENT 'Original ( listed ) price of a  returned product gross in local currency',
	PROD_PRICE_VAT_LOCAL_VAL NUMBER(38,5) COMMENT 'Original ( listed ) vat  on price of a returned  product in local currency',
	PROD_COUPON_NET_LOCAL_VAL NUMBER(38,5) COMMENT 'An amount of discount coupon for a  returned product net in local currency',
	PROD_COUPON_GROSS_LOCAL_VAL NUMBER(38,5) COMMENT 'An amount of discount coupon for a  returned product gross in local currency',
	PROD_COUPON_VAT_LOCAL_VAL NUMBER(38,5) COMMENT 'A vat for amount of discount coupon for a returned product in local currency',
	DELIVERY_COST_NET_LOCAL_VAL NUMBER(38,5) COMMENT 'A returned article specific delivery costs netto in local currency. This cost is optional and mostly article dependent. An example is a fridge which has additional delivery costs.',
	DELIVERY_COST_GROSS_LOCAL_VAL NUMBER(38,5) COMMENT 'A returned article  specific delivery costs gross in local currency. This cost is optional and mostly article dependent. An example is a fridge which has additional delivery costs.',
	DELIVERY_COST_VAT_LOCAL_VAL NUMBER(38,5) COMMENT 'A returned article  specific delivery vat value in local currency. This tax value is optional and mostly article dependent. An example is a fridge which has additional delivery costs for which taxes might have to be paid.',
	DELIVERY_COUPON_NET_LOCAL_VAL NUMBER(38,5) COMMENT 'A discount value netto for  returned article specific delivery costs in local currency.',
	DELIVERY_COUPON_GROSS_LOCAL_VAL NUMBER(38,5) COMMENT 'A discount value gross for  returned article specific delivery costs in local currency.',
	DELIVERY_COUPON_VAT_LOCAL_VAL NUMBER(38,5) COMMENT 'A discount vat value for  returned article specific delivery costs in local currency.',
	DELIVERY_PAUSHAL_GROSS_LOCAL_VAL NUMBER(38,5) COMMENT 'A paushal for delivery costs splitted per every order position in gross and local currency',
	DELIVERY_PAUSHAL_NET_LOCAL_VAL NUMBER(38,5) COMMENT 'A paushal for delivery costs splitted per every order position in netto and local currency',
	DELIVERY_PAUSHAL_VAT_LOCAL_VAL NUMBER(38,5) COMMENT 'The vat value of the paushal delivery costs splitted per every order position in local currency',
	DELIVERY_PAUSHAL_COUPON_NET_LOCAL_VAL NUMBER(38,5) COMMENT 'A discount value netto for paushal delivery cost splitted per every order position in local currency',
	DELIVERY_PAUSHAL_COUPON_GROSS_LOCAL_VAL NUMBER(38,5) COMMENT 'A discount value gross for paushal delivery cost splitted per every order position in local currency',
	DELIVERY_PAUSHAL_COUPON_VAT_LOCAL_VAL NUMBER(38,5) COMMENT 'A discount vat value for paushal delivery cost splitted per every order position in local currency',
	COGS_PRICE_NET_LOCAL_VAL NUMBER(38,5) COMMENT 'Cost-of-Goods-sold, short: CoGs. Needed for calc of margin (= revenue - cogs )',
	DROPSHIPMENT_ORDER_FG BOOLEAN COMMENT 'In case the material is being sent from the supplier_1 this field will be filled.',
	CUST_ORDER_TYPE_CD VARCHAR(5) COMMENT 'The differenciation whether the order will be fulfilled by Lidl (=intercompany) or a supplier_1 directly (= extracompnay).',
	DELIVERY_CUST_NR VARCHAR(20) COMMENT 'Customer to whom the order was delivered ',
	DELIVERY_ADDR_NR VARCHAR(20) COMMENT 'The unique identifier (sk) for the delivery address_1',
	BILLING_ADDR_NR VARCHAR(20) COMMENT 'The unique identifier (sk) for the billing address_1',
	PROD_RETURN_REASON_CD VARCHAR(5) COMMENT 'The code for the article return reason on position level  (101, 900, etc)',
	CUST_PAYM_METHOD_CD VARCHAR(5) COMMENT 'The code for the payment methods ',
	IS_LEGACY_FG BOOLEAN COMMENT 'Technical field used to identify legacy data, for further use as a filter condition',
	DWH_CREATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
	DWH_UPDATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was last updated.',
	DWH_SRC_FILE_NAME VARCHAR(255) NOT NULL COMMENT 'The path and the name of the file(s) from which this record was loaded.',
	SRC_FILE_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was extracted from the source.',

	LEAD_SRC_LOG_SYS_CD VARCHAR(5) COMMENT 'SAP MANDT code associated with the source system',
	LEAD_SRC_NAME VARCHAR(100) COMMENT 'Source system from which the record was fetched (RJI or SEP)',
	
	CONSTRAINT PK_T_FACT_CUSTOMER_RETURN_LINE PRIMARY KEY (CUST_ORDER_RETURN_NR, CUST_ORDER_RETURN_POS_NR)
) COMMENT = 'Legacy data contains historical records with details of individual returned items';
